mapper.select:
SELECT unique_id, process_route_data_code, procedure_code primary_key
FROM ${tableName} a
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  and process_route_data_code = #{processRoute}
  and unique_id is not null

SELECT *
FROM ${tableName} a
WHERE enterprise_code = #{enterpriseCode}
AND delete_flag = 'f' and exists (
select 1 from ${gyToGxTableName} b ,${partToGyTableName} c
where a.primary_key=b.procedure_code
and b.enterprise_code = #{enterpriseCode}
AND b.delete_flag = 'f'
and c.delete_flag = 'f'
and c.enterprise_code = #{enterpriseCode}
and c.process_route_data_code=b.process_route_data_code
and c.product_part_code in

    #{item}

and c.unique_id = b.unique_id;
)

SELECT a.*,c.product_part_code  ,c.unique_id ,b.process_route_data_code
FROM ${tableName} a ,${gyToGxTableName} b ,${partToGyTableName} c
WHERE a.enterprise_code = #{enterpriseCode}
AND a.delete_flag = 'f' and a.primary_key=b.procedure_code
and b.enterprise_code = #{enterpriseCode}
AND b.delete_flag = 'f'
and c.delete_flag = 'f'
and c.enterprise_code = #{enterpriseCode}
and c.process_route_data_code=b.process_route_data_code
and c.product_part_code in

    #{item}

and c.unique_id = b.unique_id;
